// Get the output from the AI Agent
const item = $input.first();
const outputString = item.json.output;

// Remove the ```json and ``` markdown wrapper if present
let cleanedString = outputString.trim();

// Remove markdown code fences more aggressively
cleanedString = cleanedString
  .replace(/^```json\s*/i, '')  // Remove opening ```json
  .replace(/^```\s*/i, '')       // Remove opening ```
  .replace(/```\s*$/i, '')       // Remove closing ```
  .trim();

// If the string doesn't end with ], try to close it properly
if (!cleanedString.endsWith(']')) {
  const openBrackets = (cleanedString.match(/\[/g) || []).length;
  const closeBrackets = (cleanedString.match(/\]/g) || []).length;
  const openBraces = (cleanedString.match(/\{/g) || []).length;
  const closeBraces = (cleanedString.match(/\}/g) || []).length;

  for (let i = 0; i < (openBraces - closeBraces); i++) {
    cleanedString += '\n  }';
  }
  for (let i = 0; i < (openBrackets - closeBrackets); i++) {
    cleanedString += '\n]';
  }
}

// Parse the JSON string
let parsedData;
try {
  parsedData = JSON.parse(cleanedString);
} catch (error) {
  const jsonObjects = [];
  const regex = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g;
  let match;

  while ((match = regex.exec(outputString)) !== null) {
    try {
      const obj = JSON.parse(match[0]);
      if (obj.Question || obj.question) {
        jsonObjects.push(obj);
      }
    } catch (e) {
      continue;
    }
  }

  if (jsonObjects.length > 0) {
    parsedData = jsonObjects;
  } else {
    throw new Error('Failed to parse JSON: ' + error.message + '\n\nReceived: ' + cleanedString.substring(0, 500));
  }
}

// Helper function to ensure marks are valid
function validateMarks(marks) {
  if (!marks || marks === "") return "1"; // Default to 1 if missing
  const marksNum = parseInt(marks);
  if (isNaN(marksNum) || marksNum < 1) return "1";
  if (marksNum > 10) return "6"; // Cap at reasonable maximum
  return marks.toString();
}

// If parsedData is an array, map each item to the output format
if (Array.isArray(parsedData)) {
  return parsedData.map(record => ({
    json: {
      "Sr No": record["Sr No"] || record.sr_no || '',
      "Type of Question": record["Type of Question"] || record.question_type || 'DES',
      "Question": record.Question || record.question || '',
      "Image or Special Words Change": record["Image or Special Words Change"] || record.image_or_special_words_change || 'NA',
      "I": record.I || record.option_1 || '',
      "II": record.II || record.option_2 || '',
      "III": record.III || record.option_3 || '',
      "IV": record.IV || record.option_4 || '',
      "Correct Option(s)": record["Correct Option(s)"] || record.correct_options || '',
      "Correct Answer": record["Correct Answer"] || record.correct_answer || '',
      "Subject": record.Subject || record.subject || '',
      "Marks": validateMarks(record.Marks || record.marks), // SMART VALIDATION
      "Exam Flag": record["Exam Flag"] || record.exam_flag || '',
      "Section": record.Section || record.section || '',
      "Language": record.Language || record.language || 'English',
      "Exam QNo": record["Exam QNo"] || record.exam_qno || '',
      "Option": record.Option || record.option || '',
      "VidyaMine Approach": record["VidyaMine Approach"] || record.approach || '',
      "Solution": record.Solution || record.solution || record.answer || '',
      "Topic": record.Topic || record.topic || '',
      "Time Duration": record["Time Duration"] || record.time_duration || '',
      "Difficulty": record.Difficulty || record.difficulty || '',
      "Knowledge Type": record["Knowledge Type"] || record.knowledge_type || '',
      "For Flash Card?": record["For Flash Card?"] || record.for_flashcard || '',
      "Date Extracted": record["Date Extracted"] || record.date_extracted || ''
    }
  }));
} else {
  return [{
    json: {
      "Sr No": parsedData["Sr No"] || parsedData.sr_no || '',
      "Type of Question": parsedData["Type of Question"] || parsedData.question_type || 'DES',
      "Question": parsedData.Question || parsedData.question || '',
      "Image or Special Words Change": parsedData["Image or Special Words Change"] || parsedData.image_or_special_words_change || 'NA',
      "I": parsedData.I || parsedData.option_1 || '',
      "II": parsedData.II || parsedData.option_2 || '',
      "III": parsedData.III || parsedData.option_3 || '',
      "IV": parsedData.IV || parsedData.option_4 || '',
      "Correct Option(s)": parsedData["Correct Option(s)"] || parsedData.correct_options || '',
      "Correct Answer": parsedData["Correct Answer"] || parsedData.correct_answer || '',
      "Subject": parsedData.Subject || parsedData.subject || '',
      "Marks": validateMarks(parsedData.Marks || parsedData.marks), // SMART VALIDATION
      "Exam Flag": parsedData["Exam Flag"] || parsedData.exam_flag || '',
      "Section": parsedData.Section || parsedData.section || '',
      "Language": parsedData.Language || parsedData.language || 'English',
      "Exam QNo": parsedData["Exam QNo"] || parsedData.exam_qno || '',
      "Option": parsedData.Option || parsedData.option || '',
      "VidyaMine Approach": parsedData["VidyaMine Approach"] || parsedData.approach || '',
      "Solution": parsedData.Solution || parsedData.solution || parsedData.answer || '',
      "Topic": parsedData.Topic || parsedData.topic || '',
      "Time Duration": parsedData["Time Duration"] || parsedData.time_duration || '',
      "Difficulty": parsedData.Difficulty || parsedData.difficulty || '',
      "Knowledge Type": parsedData["Knowledge Type"] || parsedData.knowledge_type || '',
      "For Flash Card?": parsedData["For Flash Card?"] || parsedData.for_flashcard || '',
      "Date Extracted": parsedData["Date Extracted"] || parsedData.date_extracted || ''
    }
  }];
}

// Access binary data from the first input item
const item = $input.first();
const bin = item.binary?.Upload_Excel_Sheet_for_extracting_Topics;

let filename = null;
let extension = null;
let fileTypeFlag = "OTHER";

if (bin && bin.fileName) {
  filename = bin.fileName;
  const parts = filename.split(".");
  extension = parts.length > 1 ? parts.pop().toLowerCase() : null;
  if (["xlsx", "xls"].includes(extension)) {
    fileTypeFlag = "EXCEL";
  }
}

// RETURN both JSON + the original binary file
return {
  json: {
    filename,
    fileExtension: extension,
    fileTypeFlag
  },
  binary: {
    Upload_Excel_Sheet_for_extracting_Topics: bin
  }
};

// The merge node gives an array of items
const itemsArray = items.map(i => i.json);

// First element contains the Q/A extracted text
const first = itemsArray[0];

// Extract text safely
let data = null;
try {
  data = first.content.parts[0].text;
} catch (e) {
  data = "";
}

// Remaining items are topics
const topics = itemsArray.slice(1).map(t => ({
  chapter_name: t.chapter_name,
  name: t.name
}));

return [
  {
    json: {
      data,
      topics
    }
  }
];
